<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$start=(int)$_POST['start'];$end=(int)$_POST['end'];if($start<1||$end<$start){$error='Use a valid registration range.';}else{try{$p=db();$p->beginTransaction();$p->prepare('INSERT INTO batches(department_id,batch_name,batch_code,academic_year,registration_prefix,registration_start,registration_end) VALUES(?,?,?,?,?,?,?)')->execute([$_SESSION['user']['department_id'],trim($_POST['name']),trim($_POST['code']),trim($_POST['year']),trim($_POST['prefix']),$start,$end]);$id=(int)$p->lastInsertId();$ins=$p->prepare('INSERT INTO students(batch_id,registration_number) VALUES(?,?)');for($n=$start;$n<=$end;$n++)$ins->execute([$id,trim($_POST['prefix']).'/'.str_pad((string)$n,3,'0',STR_PAD_LEFT)]);$p->commit();flash('Batch created and '.($end-$start+1).' students generated.');redirect('/hod/batches/index.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error='Unable to create batch. Check that the batch code and registration prefix are unique.';}}}$title='Create Batch';require __DIR__.'/../../includes/header.php';?><section class="panel"><h2>Create Batch</h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Batch Name<input name="name" required></label><label>Batch Code<input name="code" required></label><label>Academic Year<input name="year" required></label><label>Registration Prefix<input name="prefix" placeholder="ANU/IT/2324/F" required></label><div class="inline-form"><label>Start<input name="start" type="number" min="1" required></label><label>End<input name="end" type="number" min="1" required></label></div><button>Create Batch &amp; Students</button></form></section><?php require __DIR__.'/../../includes/footer.php';?>
